MATH={
'residual':[r'e_i=f_o(\mathbf x_i)-y_i',r'\mathbf e=(1,1,1,10)'],
'squared':[r'L_{\rm sq,sum}=\sum_{i=1}^{b}e_i^2',r'1^2+1^2+1^2+10^2=103'],
'absolute':[r'L_{\rm abs,sum}=\sum_{i=1}^{b}|e_i|',r'|1|+|1|+|1|+|10|=13'],
'huber':[r'|e|\le\delta:\ h_\delta(e)=\frac12e^2',r'|e|>\delta:\ h_\delta(e)=\delta(|e|-\frac12\delta)',r'\delta>0'],
'huberexample':[r'\delta=1',r'h_1(1)=\frac12(1)^2=\frac12,\quad h_1(10)=1(10-\frac12)=9.5',r'\frac12+\frac12+\frac12+9.5=11'],
'summean':[r'\mathrm{MSE}=\frac{103}{4}=25.75',r'\mathrm{MAE}=\frac{13}{4}=3.25',r'\bar h=\frac{11}{4}=2.75'],
'outlier':[r'\frac{100}{103}\approx97.09\%',r'\frac{10}{13}\approx76.92\%',r'\frac{9.5}{11}\approx86.36\%'],
'curves':[r'e^2',r'|e|',r'h_1(e)'],
'crossentropy':[r'L_{\rm CE}=-\sum_{i=1}^{b}\sum_{l=1}^{c}y_{il}\ln p_{il}',r'\ell=-\ln p_{\rm true}',r'\sum_l p_l=1'],
'cecalc':[r'\mathbf a=(2,1,0),\quad S=e^2+e+1',r'\mathbf p=(e^2,e,1)/S',r'-\ln(e^2/S)\approx0.408',r'-\ln(e/S)\approx1.408',r'-\ln(1/S)\approx2.408'],
'binary':[r'\ell=-y\ln p-(1-y)\ln(1-p)',r'y\in\{0,1\},\quad0<p<1'],
'kl':[r'D_{\rm KL}(\mathbf y\Vert\mathbf p)=\sum_l y_l\ln\frac{y_l}{p_l}',r'\sum_l y_l=\sum_l p_l=1',r'y_l>0\Rightarrow p_l>0'],
'klcalc':[r'\mathbf y=(0.7,0.2,0.1)',r'\sum_l y_l\ln(y_l/p_l)\approx0.005787'],
'relation':[r'H(\mathbf y,\mathbf p)=H(\mathbf y)+D_{\rm KL}(\mathbf y\Vert\mathbf p)',r'H(\mathbf y)=-\sum_l y_l\ln y_l',r'\mathbf y=(1,0,0)\Rightarrow H(\mathbf y)=0'],
'hinge':[r'\ell=\max(0,m-yf_o),\quad m=1',r'y\in\{-1,+1\},\quad yf_o\ge m\Rightarrow\ell=0'],
'hingecalc':[r'y=+1,\quad m=1',r'\max(0,1-1.5)=0',r'\max(0,1-0.3)=0.7',r'\max(0,1-(-0.5))=1.5'],
'margin':[r's=\mathbf w^\top\mathbf x+b',r'd=\frac{s}{\|\mathbf w\|_2}',r'(\mathbf w,b)\mapsto(2\mathbf w,2b):\ s\mapsto2s,\ d\mapsto d'],
'join':[r'h_\delta(\pm\delta)=\frac12\delta^2',r'h_\delta^{\prime}(+\delta)=+\delta',r'h_\delta^{\prime}(-\delta)=-\delta'],
'next':[r'\ell=(f_o-y)^2'],
'practice1':[r'\mathbf e=(2,-1,0.5,6),\quad\delta=1'],
'practice2':[r'\mathbf a=(0,0,0),\quad\ell=-\ln p_{\rm true}=?'],
'practice3':[r'y=-1,\quad f_o=0.8,\quad\ell=\max(0,1-yf_o)=?'],
}
